public String render(String template, Map<String, Object> params) {
    String sql = template;
    // {{#if}} 与 {{#in}} 必须先展开，否则下面的 :param 会误伤块内的占位符
    sql = renderIfBlocks(sql, params);
    sql = renderInBlocks(sql, params);
    // :param 一律替换成 #{param}，值永远不进 SQL 文本
    Matcher m = PARAM_PATTERN.matcher(sql);
    StringBuffer sb = new StringBuffer();
    while (m.find()) {
        String name = m.group(1);
        if (!params.containsKey(name)) {
            throw new BizException("缺少模板参数: " + name);
        }
        m.appendReplacement(sb, "#{" + name + "}");
    }
    m.appendTail(sb);
    return sb.toString();
}

private String renderIfBlocks(String sql, Map<String, Object> params) {
    // 条件块的参数为空时，整段（含 AND）一起删掉
    Matcher m = IF_PATTERN.matcher(sql);
    StringBuffer sb = new StringBuffer();
    while (m.find()) {
        String name = m.group(1);
        String body = m.group(2);
        boolean keep = params.get(name) != null;
        m.appendReplacement(sb, keep ? Matcher.quoteReplacement(body) : "");
    }
    m.appendTail(sb);
    return sb.toString();
}

private static final List<Pattern> DANGEROUS = List.of(
        Pattern.compile("(?i)\\b(union\\s+all|union\\s+select)\\b"),
        Pattern.compile("(?i)\\b(sleep|benchmark)\\s*\\("),
        Pattern.compile("(?i);\\s*\\w"),
        // …共 13 条：注释注入、堆叠语句、延时函数、文件读写、系统表访问
);

public void checkSelect(String sql) {
    String head = sql.trim().toLowerCase();
    // 只允许查询：必须以 select 或 with 开头
    if (!head.startsWith("select") && !head.startsWith("with")) {
        throw new BizException("只允许查询语句");
    }
    for (Pattern p : DANGEROUS) {
        if (p.matcher(sql).find()) {
            throw new BizException("SQL 含不允许的结构: " + p.pattern());
        }
    }
}
